// OTHVM — final output normalizer: compact JSON, capped strings, capped total size
const out = [];
let total = 0;
for (const item of $input.all().slice(0, 25)) {
  if (item.error) { const e = item.error; const msg = [e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error'; out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  const j = item.json || {};
  if (j.ok === false || (Object.keys(j).length === 1 && 'error' in j)) { const e = j.error; const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? ([e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error') : String(e || 'unknown error')); out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  if (typeof j.operation === 'string' && /^[a-z]+[A-Za-z0-9]*.[a-zA-Z][A-Za-z0-9]*$/.test(j.operation) && j.id === undefined && j.ok !== true) { out.push({ json: { ok: false, error: 'الأداة مرجّعتش نتيجة تنفيذ حقيقية — الأغلب فشل (مصادقة أو اتصال أو مدخلات ناقصة). راجع الإعدادات أو جرّب تاني.' } }); continue; }
  const o = {};
  for (const [k, v] of Object.entries(j)) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'string') o[k] = v.length > 400 ? v.slice(0, 400) + '\u2026' : v;
    else if (typeof v === 'object') { const s = JSON.stringify(v); o[k] = s.length > 500 ? s.slice(0, 500) + '\u2026' : v; }
    else o[k] = v;
  }
  if (!Object.keys(o).length) continue;
  const s = JSON.stringify(o);
  if (total + s.length > 12000) break;
  total += s.length;
  out.push({ json: o });
}
return out.length ? out : [{ json: { ok: true, note: 'no results' } }];

const KEYS = ['id','number','title','name','full_name','state','body','html_url','url','download_url','tag_name','draft','prerelease','created_at','updated_at','pushed_at','size','language','description','default_branch','private','archived','forks_count','stargazers_count','open_issues_count','sha','message','status','total_downloads','total_count','download_count','content','path','type','merged','event','conclusion','head_branch','run_number','workflow_id','ref','commit_id','date'];
const cap = (s) => typeof s === 'string' ? (s.length > 220 ? s.slice(0, 220) + '...' : s) : s;
const pick = (x) => {
  const o = {};
  for (const k of KEYS) { const v = x[k]; if (v === undefined || v === null || v === '' || typeof v === 'object') continue; o[k] = cap(v); }
  if (x.user && typeof x.user === 'object') o.user = x.user.login || x.user.name || x.user.id;
  if (x.owner && typeof x.owner === 'object') o.owner = x.owner.login;
  if (x.license && typeof x.license === 'object') o.license = x.license.spdx_id || x.license.name;
  if (x.base && typeof x.base === 'object') o.base = x.base.ref;
  if (x.head && typeof x.head === 'object') o.head = x.head.ref;
  if (x.merged_at) o.merged_at = x.merged_at;
  return o;
};
const out = [];
for (const item of $input.all()) {
  if (item.error) { const _e = item.error; out.push({ json: { ok: false, error: String((_e && (_e.description || _e.message)) || _e || 'unknown error').slice(0, 400) } }); continue; }
  const r = item.json || {};
  if (Array.isArray(r)) { for (const x of r.slice(0, 20)) out.push({ json: pick(x) }); continue; }
  if (Array.isArray(r.workflows)) { for (const x of r.workflows.slice(0, 20)) out.push({ json: pick(x) }); continue; }
  if (r.workflow && typeof r.workflow === 'object' && !Array.isArray(r.workflow)) { out.push({ json: pick(r.workflow) }); continue; }
  const o = pick(r);
  out.push({ json: Object.keys(o).length ? o : r });
}
return out.length ? out : [{ json: { ok: true, note: 'no results' } }];

